ick="saveDraft">按版本保存草稿</button><button v-if="can('validate')" :disabled="busy || !draft" @click="validateDraft">校验当前草稿</button><p v-if="validation">校验 {{ validation.outcome }} · 版本 {{ validation.draftRevision }}；{{ validation.findings?.join('；') }}</p><button v-if="can('publish')" :disabled="busy || publishDisabled" @click="publish">由管理者明确发布</button><p v-if="publicationOperation">发布操作 {{ publicationOperation.state }}；<template v-if="publicationReceiptComplete">不可变发布结果 {{ publicationOperation.result.state }} / 初始核验 {{ publicationOperation.result.readbackState }}；<template v-if="publicationOperation.verification.state==='FAILED'">发布已提交，阅读核验异常。</template><template v-else-if="publicationOperation.verification.state==='PASSED'">阅读核验已通过。</template><template v-else>当前核验待确认。</template></template><template v-else>尚未取得完整权威回执。</template><button v-if="publicationBinding" :disabled="busy" type="button" @click="refreshPublication">刷新原发布操作/当前核验</button><button v-if="publicationReadable" type="button" @click="openEdition(publicationOperation.result.workId,publicationOperation.result.editionId)">阅读已核验版本</button></p></template>
