rm v-if="can('edition.withdraw') && history" @submit.prevent="withdrawEdition"><label>下架原因 <input v-model.trim="withdraw.reason" required /></label><label>替代 active 版本 <select v-model="withdraw.replacementActiveEditionId"><option :value="null">null：明确下架</option><option v-for="candidate in eligibleReplacement" :key="candidate.editionId" :value="candidate.editionId">{{ candidate.editionId }}</option></select></label><button :disabled="busy">显式下架此版本</button></form></article></section>
    </template>
