<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { registerIdentityCleanup } from '@/utils/identityLifecycle.js'
import { ARCHIVE_COLLECTION_ID, ARCHIVE_SKILL, createArchiveMaintenanceGateway, createIdentityFence } from '@/composables/juyiting/useArchiveMaintenance.js'
const props = defineProps({ gateway: { type: Object, default: null } })
const emit = defineEmits(['open-maintenance-entry','open-edition'])
const gateway = props.gateway || createArchiveMaintenanceGateway()
const tabs=Object.freeze([{id:'appointments',label:'任职'},{id:'jobs',label:'维护单'},{id:'history',label:'版本与记录'}]); const tabButtons=ref([]); const activeTab=ref('jobs')
const capabilities = ref(null), slot = ref(null), appointments = ref([]), jobs = ref([]), job = ref(null), events = ref([]), draft = ref(null), recoveryContext = ref(null), validation = ref(null), draftJson = ref(''), selectedJobId = ref(''), confirmation = ref(null), installationStatus = ref(null), catalog = ref([]), works = ref([]), history = ref(null), editionDetail = ref(null), selectedEditionId = ref(''), editionReaderSnapshot = ref(null), editionReadError = ref(''), comparisonEdition = ref(null), comparisonEditionId = ref(''), comparisonReaderSnapshot = ref(null), comparisonReadError = ref(''), selectedWorkId = ref(''), selectedBlockId = ref(''), blockEditor = ref(null), blockJson = ref(''), blockForm = ref({title:'',ordinal:1,paragraphs:[]}), metadataEditor = ref({blocks:[],excludedSourceRangesJson:'[]'}), sourceOperation = ref(null), publicationOperation = ref(null), publicationBinding = ref(null), unknownIntents = ref([]), catalogError = ref(''), loading = ref(false), busy = ref(false), error = ref(''), message = ref('')
const appointment = ref({ agentId:'', expectedBindingVersion:'', permissionProfile:'DRAFT_ONLY', workScopeMode:'COLLECTION', workIds:[] }), installation = ref({ agentId:'', bindingVersion:'' }), sourceInput = ref({ sourceName:'', sourceVersion:'', rightsBasis:'' }), sourceFileInput = ref(null), sourceFile = ref(null), preparedSource = ref(null), request = ref({ operation:'ADD_WORK', newWork:{ canonicalKey:'', title:'', language:'zh' }, workId:'', sourceId:'', requestedPublicationMode:'MANUAL' }), recovery = ref({ reason:'' }), reassignment = ref({ newAppointmentId:'' }), resolve = ref({ sourceId:'', newWork:{canonicalKey:'',title:'',language:'zh'} }), withdraw = ref({ reason:'', replacementActiveEditionId:null })
const identity = createIdentityFence(); let readSequence = 0; let blockSequence = 0; let historySequence = 0; let editionSequence = 0; let comparisonSequence = 0; let operationSequence = 0; let authoritySignature = ''; let busyOwner = 0; let unregister = null; const publicationRecords = new Map()
const can = action => capabilities.value?.allowedActions?.includes(action) ?? false
const canHistory = computed(() => can('publish') || can('edition.withdraw'))
const hasAccess = computed(() => ['appoint','job.create','source.prepare','job.read','job.manage','publish','edition.withdraw'].some(can))
const activeAppointments = computed(() => appointments.value.filter(x => x?.status === 'ACTIVE'))
const currentAppointment = computed(() => activeAppointments.value[0] || null)
const decimalString = value => /^(?:0|[1-9][0-9]*)$/.test(typeof value === 'string' ? value : '')
const jobHandling = computed(() => {
  const value = job.value?.handling
  if (!value || typeof value !== 'object' || Array.isArray(value) || !['ACTIVE','REVOKED','BINDING_CHANGED','UNASSIGNED','UNVERIFIED'].includes(value.assignmentStatus)) return null
  const progress = value.progress
  if (!progress || typeof progress !== 'object' || !decimalString(progress.completedChapters) || typeof progress.totalKnown !== 'boolean') return null
  if (progress.totalKnown !== decimalString(progress.totalChapters) || (!progress.totalKnown && progress.totalChapters !== null)) return null
  return value
})
const jobAssignmentSnapshot = computed(() => jobHandling.value?.assignmentSnapshot && typeof jobHandling.value.assignmentSnapshot === 'object' ? jobHandling.value.assignmentSnapshot : null)
const jobProgressLabel = computed(() => {
  const progress = jobHandling.value?.progress
  if (!progress) return '未知（服务端未提供可信总章数）'
  return progress.totalKnown ? `${progress.completedChapters} / ${progress.totalChapters}` : `${progress.completedChapters} 章完成；总章数未知`
})
const jobAssignmentLabel = computed(() => {
  const handling = jobHandling.value
  if (!handling) return '当前任职未获服务器验证'
  if (handling.assignmentStatus === 'ACTIVE' && handling.assignedAgentId && handling.permissionProfile) return `${handling.assignedAgentId} · ${handling.permissionProfile}`
  if (handling.assignmentStatus === 'REVOKED' || handling.assignmentStatus === 'BINDING_CHANGED') return '当前任职已失效，需要重新改派'
