const publicationBindingMatchesCurrent = binding => Boolean(binding && job.value?.jobId===binding.jobId && selectedJobId.value===binding.jobId && draft.value?.draftId===binding.draftId && String(draft.value?.revision)===binding.draftRevision)
const currentPublicationRetained = computed(() => { const intent=draft.value?.draftId?publicationIntent(draft.value.draftId):null; return intent ? unknownIntents.value.find(item=>item.intent===intent) || gateway.retainedIntent?.(intent) || null : null })
