const publishDisabled = computed(() => validation.value?.outcome !== 'PASSED' || publicationSubmitted.value)
const current = epoch => identity.isCurrent(epoch)
const sameSelection = (epoch, sequence, id) => current(epoch) && readSequence === sequence && selectedJobId.value === id
