const moveTab=async(index,delta)=>{const next=(index+delta+tabs.length)%tabs.length;activeTab.value=tabs[next].id;await nextTick();tabButtons.value?.[next]?.focus?.()}
const blockSummaries = snapshot => [snapshot?.catalog?.activeEdition?.preface, ...(snapshot?.catalog?.activeEdition?.chapters || [])].filter(Boolean)
const blockIdentity = block => block?.blockType === 'PREFACE' ? 'PREFACE' : `${block?.blockType}:${block?.number}`
const paragraphPreview = value => String(value || '').replace(/\s+/g, ' ').trim().slice(0, 96)
const editionDiff = computed(() => {
  const left = editionReaderSnapshot.value, right = comparisonReaderSnapshot.value
  if (!left || !right) return []
  const rows = [{ key: 'editions', text: `版本 ${left.editionId} 与 ${right.editionId} 的真实 Reader 内容比较` }]
  const leftBlocks = new Map(left.blocks.map(block => [blockIdentity(block), block]))
  const rightBlocks = new Map(right.blocks.map(block => [blockIdentity(block), block]))
  for (const key of new Set([...leftBlocks.keys(), ...rightBlocks.keys()])) {
