  await refreshPublicationForBinding(binding,epoch)
},'发布已提交；请读取原操作核验，任何核验状态都不会重复发布。')
const resolveInput = () => run(async epoch=>{const id=job.value?.jobId, snapshot=resolveAppointment.value, add=job.value?.operation==='ADD_WORK'; if(!snapshot?.appointmentId||snapshot.revision==null||!snapshot.requiredSkill)throw new Error('当前没有可用于补全的服务端任职快照'); const sourceId=job.value?.sourceId||resolve.value.sourceId||null, workId=add?null:job.value?.workId||null, needsNewWork=add&&!job.value?.workId, newWork=needsNewWork?{...resolve.value.newWork}:null; if(!sourceId||(!add&&!workId)||(needsNewWork&&(!newWork?.canonicalKey||!newWork?.title||!newWork?.language)))throw new Error('仅补齐服务端标记为缺失的来源或作品字段'); await gateway.resolveInput(id,{sourceId,newWork,workId,expectedAppointmentId:snapshot.appointmentId,expectedAppointmentRevision:exactRevision(snapshot.revision),expectedSkill:snapshot.requiredSkill},exactRevision(job.value?.revision));if(current(epoch))await openJob(id)},'已补全未冻结输入；维护单状态以服务端为准。')
const loadBlock = async () => { const epoch=identity.current(), sequence=++blockSequence, id=draft.value?.draftId, blockId=selectedBlockId.value; if(!id||!blockId)return; const guard=()=>current(epoch)&&sequence===blockSequence&&draft.value?.draftId===id&&selectedBlockId.value===blockId; try { const value=await gateway.draftBlock(id,blockId); if(!guard())return; blockEditor.value=value; blockJson.value=JSON.stringify(value.block,null,2); blockForm.value={title:value.block?.title||'',ordinal:Number(value.block?.ordinal||1),paragraphs:(value.block?.paragraphs||[]).map(item=>({ordinal:Number(item.ordinal||1),text:item.text||'',sourceRangesJson:JSON.stringify(item.sourceRanges||[])}))} } catch(x){if(guard()){if(isAuthFailure(x))failClosed();else error.value=fail(x)}} }
const patchDraftMetadata = () => run(async epoch=>{const body={blocks:metadataEditor.value.blocks.map(item=>({blockKey:item.blockKey,ordinal:Number(item.ordinal),title:item.title,titleSourceRanges:JSON.parse(item.titleSourceRangesJson||'[]')})),excludedSourceRanges:JSON.parse(metadataEditor.value.excludedSourceRangesJson||'[]')};const value=await gateway.patchDraft(draft.value.draftId,body,exactRevision(draft.value.revision));if(!current(epoch))return;draft.value=value;validation.value=null},'目录、顺序与排除范围已保存；旧校验已失效。')
const saveBlockBody = body => run(async epoch=>{const id=draft.value?.draftId, blockId=selectedBlockId.value; const value=await gateway.putDraftBlock(id,blockId,body,exactRevision(draft.value?.revision)); if(!current(epoch)||draft.value?.draftId!==id||selectedBlockId.value!==blockId)return; blockEditor.value=value; validation.value=null; await openJob(job.value?.jobId)},'章节已按草稿版本保存；旧校验已失效。')
const saveBlock = () => { const old=blockEditor.value?.block||{}; return saveBlockBody({blockType:old.blockType,blockKey:old.blockKey,ordinal:Number(blockForm.value.ordinal),title:blockForm.value.title,titleSourceRanges:old.titleSourceRanges||[],paragraphs:blockForm.value.paragraphs.map(item=>({ordinal:Number(item.ordinal),text:item.text,sourceRanges:JSON.parse(item.sourceRangesJson||'[]')}))}) }
const saveAdvancedBlock = () => saveBlockBody(JSON.parse(blockJson.value))
const readerSnapshot = async (workId,editionId) => { const catalogValue=await gateway.readerCatalog(editionId); const active=catalogValue?.activeEdition; if(catalogValue?.workId!==workId||active?.editionId!==editionId||!active?.manifestSha256)throw new Error('Reader 精确版本目录与管理版本不一致'); const summaries=blockSummaries({catalog:catalogValue}); const blocks=await Promise.all(summaries.map(async summary=>{const block=await gateway.readerBlock(editionId,summary);if(block?.editionId!==editionId||block?.manifestSha256!==active.manifestSha256||block?.blockId!==summary.blockId||block?.blockType!==summary.blockType||!Array.isArray(block?.paragraphs)||block.paragraphCount!==block.paragraphs.length)throw new Error('Reader 精确版本正文与目录不一致');return block})); return {workId,editionId,catalog:catalogValue,blocks} }
const loadHistory = async () => { const epoch=identity.current(), sequence=++historySequence, id=selectedWorkId.value; editionSequence++;comparisonSequence++;history.value=null;editionDetail.value=null;selectedEditionId.value='';editionReaderSnapshot.value=null;editionReadError.value='';comparisonEdition.value=null;comparisonEditionId.value='';comparisonReaderSnapshot.value=null;comparisonReadError.value='';if(!id)return;const guard=()=>current(epoch)&&sequence===historySequence&&selectedWorkId.value===id;try{const value=await gateway.editionHistory(id);if(guard())history.value=value}catch(x){if(guard()){if(isAuthFailure(x))failClosed();else error.value=fail(x)}} }
const loadEdition = async editionId => { const epoch=identity.current(), sequence=++editionSequence, workSequence=historySequence, workId=selectedWorkId.value;selectedEditionId.value=editionId;editionDetail.value=null;editionReaderSnapshot.value=null;editionReadError.value='';if(!workId||!editionId)return;const guard=()=>current(epoch)&&sequence===editionSequence&&workSequence===historySequence&&selectedWorkId.value===workId&&selectedEditionId.value===editionId;try{const value=await gateway.edition(workId,editionId);if(!guard())return;editionDetail.value=value;try{const snapshot=await readerSnapshot(workId,editionId);if(guard())editionReaderSnapshot.value=snapshot}catch(x){if(!guard())return;if(isAuthFailure(x))failClosed();else if(x?.status===410)editionReadError.value='此版本已下架，Reader 返回 410；不能伪造正文或回退到旧缓存进行比较。';else if(x?.status===404)editionReadError.value='Reader 不提供此精确版本正文，不能进行内容比较。';else error.value=fail(x)}}catch(x){if(guard()){if(isAuthFailure(x))failClosed();else error.value=fail(x)}} }
const loadComparisonEdition = async () => { const epoch=identity.current(), sequence=++comparisonSequence, workSequence=historySequence, editionId=comparisonEditionId.value,workId=selectedWorkId.value;comparisonEdition.value=null;comparisonReaderSnapshot.value=null;comparisonReadError.value='';if(!editionId)return;const guard=()=>current(epoch)&&sequence===comparisonSequence&&workSequence===historySequence&&selectedWorkId.value===workId&&comparisonEditionId.value===editionId;try{const value=await gateway.edition(workId,editionId);if(!guard())return;comparisonEdition.value=value;try{const snapshot=await readerSnapshot(workId,editionId);if(guard())comparisonReaderSnapshot.value=snapshot}catch(x){if(!guard())return;if(isAuthFailure(x))failClosed();else if(x?.status===410)comparisonReadError.value='比较版本已下架，Reader 返回 410；不会以空正文伪造差异。';else if(x?.status===404)comparisonReadError.value='Reader 不提供该比较版本正文，不能进行内容比较。';else error.value=fail(x)}}catch(x){if(guard()){if(isAuthFailure(x))failClosed();else error.value=fail(x)}} }
const withdrawEdition = () => run(async epoch=>{const snapshot={workId:selectedWorkId.value,editionId:selectedEditionId.value,detailEditionId:editionDetail.value?.editionId,workRevision:history.value?.workRevision,historySequence,editionSequence,reason:withdraw.value.reason,replacementActiveEditionId:withdraw.value.replacementActiveEditionId||null};if(!snapshot.workId||!snapshot.editionId||snapshot.editionId!==snapshot.detailEditionId||snapshot.workRevision==null)throw new Error('当前下架目标或作品版本已变化，请重新选择');await gateway.withdraw(snapshot.workId,snapshot.editionId,{reason:snapshot.reason,replacementActiveEditionId:snapshot.replacementActiveEditionId},exactRevision(snapshot.workRevision));if(current(epoch)&&historySequence===snapshot.historySequence&&editionSequence===snapshot.editionSequence&&selectedWorkId.value===snapshot.workId&&selectedEditionId.value===snapshot.editionId){await loadHistory();editionDetail.value=null}},'版本已按明确替代版或 null 下架。')
const cancelJob = () => { const reason=globalThis.prompt?.(`明确取消《${job.value?.title||''}》的维护单？请输入原因：`); if(!reason?.trim())return; return run(async epoch=>{const id=job.value.jobId;await gateway.cancel(id,{reason:reason.trim()},exactRevision(job.value.revision));if(current(epoch))await refresh()},'维护单已取消，旧执行权限被撤销。') }
const execute = () => run(async epoch=>{const id=job.value.jobId;await gateway.execute(id,exactRevision(job.value.revision));if(current(epoch))await openJob(id)},'已请求执行；请读取作业和事件确认实际状态。')
const resume = () => run(async epoch=>{const old=recoveryContext.value?.previousAppointment; if(!old)throw new Error('服务端恢复上下文不可用'); const id=job.value.jobId;await gateway.resume(id,{reason:recovery.value.reason,expectedAppointmentId:old.appointmentId,expectedAppointmentRevision:exactRevision(old.revision),expectedSkill:old.requiredSkill},exactRevision(recoveryContext.value.jobRevision));if(current(epoch))await openJob(id)},'已请求新 run/epoch；旧凭据不会被复用。')
const reassign = () => run(async epoch=>{const old=recoveryContext.value?.previousAppointment; const next=recoveryContext.value?.candidates?.find(x=>x?.appointmentId===reassignment.value.newAppointmentId);if(!old||!next)throw new Error('服务端恢复上下文不可用或未选择新任职');const id=job.value.jobId;await gateway.reassign(id,{reason:recovery.value.reason||'manager reassignment',expectedAppointmentId:old.appointmentId,expectedAppointmentRevision:exactRevision(old.revision),expectedSkill:old.requiredSkill,newAppointmentId:next.appointmentId,newAppointmentRevision:exactRevision(next.revision),newSkill:next.requiredSkill},exactRevision(recoveryContext.value.jobRevision));if(current(epoch))await openJob(id)},'已请求改派；服务端将建立新 run 并保留历史。')
const openEdition = (workId,editionId) => { if(workId&&editionId)emit('open-edition',{workId,editionId}) }
const openConversation = entry => { const value=confirmation.value;if(value?.confirmationRef)emit('open-maintenance-entry',{entry,confirmationRef:value.confirmationRef,job:value.job}) }
defineExpose({ openJobById })
onMounted(()=>{unregister=registerIdentityCleanup(clear);void refresh()});onBeforeUnmount(()=>{unregister?.();clear()})
</script>
<style scoped>.maintenance{min-height:0;overflow:auto;padding:12px;color:var(--work-ink,#242e2b);background:var(--work-paper,#fffefa)}.maintenance section{padding:12px 0;border-top:1px solid var(--work-line,#ddd)}.maintenance header{display:flex;justify-content:space-between;align-items:center;gap:8px}.maintenance form,.maintenance label{display:grid;gap:8px}.maintenance form{margin:12px 0}.maintenance fieldset{display:grid;gap:6px}.maintenance input,.maintenance select,.maintenance textarea{min-width:0;width:100%;box-sizing:border-box;padding:9px;border:1px solid #999;border-radius:6px;font:inherit}.maintenance textarea{font-family:monospace}.maintenance button{min-height:40px;margin:6px 8px 6px 0;padding:8px}.maintenance button:disabled{opacity:.5}.error{color:#9b2f26}.events{padding-left:22px}</style>
